'use strict';
const REPOSITORY = 'https://github.com/orest3781/sundercore';
const VIEWS = {today:'Today',goals:'My Goals',browse:'Browse',ideas:'More ideas',gold:'Gold routine',sources:'About the data',projects:'Crafting projects',upgrades:'Gear upgrades',overview:'Overview',field:'Field guide',inventory:'Inventory',professions:'Professions',equipment:'Armory',activity:'Outings'};
const state = {roster:[],selected:null,view:'today',filter:''};
const $ = selector => document.querySelector(selector);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const num = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const fmt = value => num(value).toLocaleString();
const percent = (value,max) => Math.min(100,Math.max(0,max ? num(value)/num(max)*100 : 0));
const money = value => {const v=Math.max(0,Math.floor(num(value)));return `${v>=10000?`${Math.floor(v/10000)}g `:''}${Math.floor(v%10000/100)}s ${v%100}c`;};
const date = value => {const d=new Date(value);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});};
const list = value => Array.isArray(value) ? value : [];
const current = () => state.roster.find(c=>c.id===state.selected) || state.roster[0];
const meter = (value,max,extra='') => `<div class="meter ${e(extra)}" role="meter" aria-label="Progress" aria-valuemin="0" aria-valuemax="${e(max||100)}" aria-valuenow="${e(Math.min(num(max||100),num(value)))}"><span style="width:${percent(value,max)}%"></span></div>`;
const empty = (title,description,icon='◇') => `<div class="empty"><span class="empty-icon" aria-hidden="true">${icon}</span><h3>${e(title)}</h3><p>${e(description)}</p></div>`;
function savedGet(key,fallback=null){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function savedSet(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function orderedGoals(c){const goals=list(c.goals), ids=list(c.nextSteps);return [...goals].sort((a,b)=>{const ai=ids.indexOf(a.id),bi=ids.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi)||num(b.priority)-num(a.priority);});}
function goalsHTML(goals,limit=6,offset=0){return goals.length?`<ol class="priorities">${goals.slice(0,limit).map((g,i)=>`<li class="priority"><span class="priority-number">${String(i+1+offset).padStart(2,'0')}</span><div class="priority-body"><h3>${e(g.title)}</h3><span class="pill ${g.status==='Ready to turn in'?'green':''}">${e(g.category||'Next step')} · ${e(g.status||'Suggested')}</span><p>${e(g.why||'')}</p>${g.action?`<details><summary>How to do it ↗</summary><p style="white-space:pre-line">${e(g.action)}</p>${g.source?`<p class="small">Source: ${e(g.source)}</p>`:''}</details>`:''}</div></li>`).join('')}</ol>`:empty('A clean slate','Capture a new snapshot in Character Ledger to bring the next steps into view.');}
function materialsHTML(c,full=false){const mats=list(c.fieldPlan?.materials);if(!mats.length)return empty('No materials queued','Pin a farming or crafting goal in the in-game planner, then share a new snapshot.','⌖');return `<div class="panel-content">${mats.map(m=>{const goal=num(m.need??m.required),owned=num(m.bag??m.owned),missing=num(m.missing),steps=[];if(m.done)steps.push('Goal ready');else{if(num(m.bank)>0)steps.push(`Withdraw ${fmt(m.bank)}`);if(num(m.make)>0)steps.push(`Craft ${fmt(m.make)}`);if(missing>0)steps.push(`${m.collect?'Collect':m.vendor?'Buy':'Acquire'} ${fmt(missing)} more`);if(!steps.length)steps.push('Review this goal');}return `<div class="farm-row"><span class="farm-icon" aria-hidden="true">▧</span><div class="farm-row-body"><div class="farm-row-title"><span>${e(m.name||`Item ${m.id}`)}</span><span class="muted">${fmt(owned)} <span class="muted">/ ${fmt(goal)}</span></span></div>${meter(owned,goal)}<small>${e(steps.join(' · '))}${m.collect?' · received this outing':' · allocated to this goal'}</small>${full?`<small>${e(m.usesText||'Pinned material goal')}${num(m.bank)?` · ${fmt(m.bank)} in last-seen bank`:''}</small>`:''}</div></div>`;}).join('')}<p class="panel-caption">Progress comes from the snapshot. Allocated materials may differ from total bag stock.</p></div>`;}
function campHTML(entry,index=0,full=false){const s=entry?.spot||{},coords=Number.isFinite(s.x)&&Number.isFinite(s.y),evidence=s.evidence||s.source||entry.evidence||'Classic-derived camp';return `<div class="camp-card"><div class="camp-art" aria-hidden="true"><div class="contour"></div><span class="compass">✧</span><span class="camp-marker">⌖</span><span class="camp-art-label">FIELD NOTES · ILLUSTRATION</span></div><h3>${e(s.name||'Unnamed camp')}</h3><div class="camp-meta">${e(s.zone||'Location not recorded')} <span class="separator">·</span> Levels ${e(s.low??'?')}–${e(s.high??'?')}</div><div class="reasons">${list(entry.reasons).map(r=>`<span class="reason">${e(r)}</span>`).join('')}</div><p class="camp-note">${e(s.note||'Explore this camp and record an outing to compare your results.')}</p><div class="camp-meta"><span class="pill">${e(evidence)}</span>${coords?` <span class="small">${(s.x*100).toFixed(1)}, ${(s.y*100).toFixed(1)}</span>`:''}</div>${entry?.comparison?`<p class="panel-caption">${e(entry.comparison)}</p>`:''}${entry?.travel?`<p class="panel-caption">${e(entry.travel)}</p>`:''}${full&&coords?`<button class="button secondary wide section-gap" data-copy-camp="${index}">Copy camp location <span aria-hidden="true">↗</span></button>`:!full?'<a class="button secondary wide section-gap" href="#field">Explore the field guide <span aria-hidden="true">↗</span></a>':''}</div>`;}
function checklistHTML(c){const tasks=list(c.fieldPlan?.tasks), checked=savedGet(`checklist:${c.id}`,[]);return `<div class="panel-content">${tasks.length?tasks.map(t=>`<label class="check-row"><input type="checkbox" data-task="${e(t)}" ${checked.includes(t)?'checked':''}><span>${e(t)}</span></label>`).join(''):'<p class="panel-caption">No outing tasks queued in this snapshot.</p>'}<p class="panel-caption">Personal checkmarks stay on this device. They do not change the character snapshot.</p></div>`;}
function hero(c){const x=c.character;return `<section class="hero" aria-label="Character"><div><div class="eyebrow"><span class="tiny-dot"></span> ${e(x.faction||'Azeroth')} · ${e(x.race||'Adventurer')}</div><h1>${e(x.name)} <span>Sundercore</span></h1><div class="hero-meta"><span class="pill ${x.classToken==='WARLOCK'?'purple':'gold'}">LEVEL ${e(x.level)} ${e((x.class||'').toUpperCase())}</span><span class="hero-description">⌖ ${e(x.zone||'Location not recorded')}</span></div></div><div class="snapshot"><div class="snapshot-label">LAST CHARACTER SNAPSHOT</div><strong>${e(date(c.exportedAt))}</strong><span>Updates after an in-game save & sync</span><br><button class="text-button" data-refresh>Refresh snapshots ↻</button></div></section>`;}
function statsHTML(c){const x=c.character,b=c.bags||{},primary=list(c.professions).filter(p=>p.isPrimary),xp=num(x.xp),max=num(x.xpForNextLevel);return `<section class="stats-grid" aria-label="At a glance"><div class="stat-card"><div class="stat-heading">Next level <span aria-hidden="true">↗</span></div><div class="stat-value">${max?Math.floor(percent(xp,max))+'%':'—'} <small>to level ${num(x.level)+1}</small></div><div class="stat-foot">${fmt(xp)} / ${fmt(max)} XP</div>${meter(xp,max,'purple')}</div><div class="stat-card"><div class="stat-heading">Carried gold <span aria-hidden="true">◉</span></div><div class="stat-value">${money(x.moneyCopper)}</div><div class="stat-foot">${num(c.fieldPlan?.budget?.shortfall)>0?`${money(c.fieldPlan.budget.shortfall)} short of rank goals`:'Available in this snapshot'}</div></div><div class="stat-card"><div class="stat-heading">Bag space <span aria-hidden="true">▦</span></div><div class="stat-value">${b.free??'—'} <small>/ ${b.capacity??'—'} free</small></div><div class="stat-foot">General-purpose slots</div>${meter(num(b.capacity)-num(b.free),b.capacity)}</div><div class="stat-card"><div class="stat-heading">Primary professions <span aria-hidden="true">⚒</span></div><div class="stat-value">${primary.length} <small>learned</small></div><div class="stat-foot">${e(primary.map(p=>p.name).join(' & ')||'A new trade awaits')}</div></div></section>`;}
function overview(c){const goals=orderedGoals(c),spots=list(c.fieldPlan?.spots);return `${statsHTML(c)}<div class="content-grid"><div class="stack"><section class="panel"><div class="panel-header"><div><h2>A worthwhile next step</h2><p>Priorities from the in-game planner</p></div><span class="pill">${goals.length} goals</span></div>${goalsHTML(goals)}${goals.length>6?`<details class="all-goals"><summary>Show ${goals.length-6} more goals</summary>${goalsHTML(goals.slice(6),goals.length,6)}</details>`:''}</section><section class="panel"><div class="panel-header"><div><h2>Before the next outing</h2><p>Your personal checklist</p></div><span aria-hidden="true" class="muted">☷</span></div>${checklistHTML(c)}</section></div><div class="stack"><section class="panel"><div class="panel-header"><div><h2>Where to grind</h2><p>Best fit in this snapshot</p></div><span aria-hidden="true" class="muted">⌖</span></div>${spots.length?campHTML(spots[0]):empty('Your next camp is unwritten','Set a material target or gain a few levels, then check the in-game field guide for a suitable camp.','⌖')}</section><section class="panel"><div class="panel-header"><div><h2>On the gathering list</h2><p>Make every outing count</p></div><a href="#field" class="small-link">View all ↗</a></div>${materialsHTML(c)}</section></div></div>`;}
function field(c){const spots=list(c.fieldPlan?.spots);return `<div class="view-header"><div><h2>Make the next outing count.</h2><p>Material goals and camps suggested for this character’s saved situation.</p></div><span class="pill">${spots.length} camp suggestions</span></div><div class="grid-two field-materials"><section class="panel"><div class="panel-header"><h2>Farming & crafting needs</h2></div>${materialsHTML(c,true)}</section><section class="panel"><div class="panel-header"><h2>Outing checklist</h2></div>${checklistHTML(c)}</section></div>${spots.length?`<div class="grid-three">${spots.map((s,i)=>`<section class="panel"><div class="panel-header"><span class="eyebrow">${i===0?'TOP MATCH':`ALTERNATIVE ${i}`}</span><span class="pill">${i===0?'Goal overlap':'Explore'}</span></div>${campHTML(s,i,true)}</section>`).join('')}</div>`:`<section class="panel">${empty('No camp recommendations yet','Use the in-game planner to choose a target. Your next published snapshot will bring those recommendations here.','⌖')}</section>`}<div class="notice">Camp order reflects level fit and overlap with your goals. Classic-derived locations need in-game confirmation on Forever. Your own recorded outings are the useful comparison for XP and loot efficiency.</div>${sourceHTML(c)}`;}
function inventory(c){const items=list(c.bags?.items),count=items.length;return `<div class="view-header"><div><h2>Everything you’re carrying.</h2><p>${fmt(count)} distinct items · ${e(c.bags?.free??'?')} general slots free · bank stock is not included here</p></div><input class="search" id="inventory-search" type="search" placeholder="Search items or item ID…" aria-label="Search inventory" value="${e(state.filter)}"></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Carried item</th><th>Item ID</th><th>Quantity</th></tr></thead><tbody id="inventory-rows">${inventoryRows(c)}</tbody></table></div></section><p class="source-note">Carried quantities combine matching items across bags, including specialized bags. The free-slot count above measures general-purpose bag space only. Snapshot: ${e(date(c.exportedAt))}.</p>`;}
function inventoryRows(c){const q=state.filter.trim().toLowerCase(),items=list(c.bags?.items).filter(i=>`${i.name} ${i.itemID}`.toLowerCase().includes(q)).sort((a,b)=>(a.name||'').localeCompare(b.name||''));return items.length?items.map(i=>`<tr><td class="item-name">${e(i.name||`Item ${i.itemID}`)}</td><td class="muted">${e(i.itemID)}</td><td>${fmt(i.count)}</td></tr>`).join(''):'<tr><td colspan="3" style="text-align:center;padding:35px">No matching items.</td></tr>';}
function professions(c){const profs=list(c.professions),goals=orderedGoals(c).filter(g=>g.category==='Professions');return `<div class="view-header"><div><h2>A craft worth mastering.</h2><p>Current skill ranks and the planner’s next training milestones.</p></div></div>${profs.length?`<div class="grid-three">${profs.map(p=>`<section class="panel profession-card"><div class="profession-top"><span class="profession-icon" aria-hidden="true">${p.name==='Fishing'?'⌁':p.name==='Cooking'?'♨':p.name==='First Aid'?'+':'⚒'}</span><span class="pill ${num(p.skill)>=num(p.maxSkill)?'gold':''}">${num(p.skill)>=num(p.maxSkill)?'AT CURRENT CAP':p.isPrimary?'PRIMARY':'SECONDARY'}</span></div><h3>${e(p.name)}</h3><div class="profession-value">${fmt(p.skill)} <small>/ ${fmt(p.maxSkill)}</small></div>${meter(p.skill,p.maxSkill)}<p class="panel-caption">${num(p.skill)>=num(p.maxSkill)?'Check rank training before the next skill-up.':`${fmt(num(p.maxSkill)-num(p.skill))} skill points to this rank’s cap.`}</p>${p.recipesCapturedAt?`<p class="panel-caption">Recipes last scanned ${e(date(p.recipesCapturedAt))}</p>`:''}</section>`).join('')}</div>`:`<section class="panel">${empty('A trade is waiting','This character has no professions recorded in the snapshot. Learn a profession in game, then save and sync.','⚒')}</section>`}${goals.length?`<section class="panel section-gap"><div class="panel-header"><h2>Profession milestones</h2></div>${goalsHTML(goals,20)}</section>`:''}`;}
const ARMORY_SLOTS = [
  [1,'head','Head','left'],[2,'neck','Neck','left'],[3,'shoulder','Shoulders','left'],
  [15,'back','Back','left'],[5,'chest','Chest','left'],[4,'shirt','Shirt','left'],
  [19,'tabard','Tabard','left'],[9,'wrist','Wrists','left'],
  [10,'hands','Hands','right'],[6,'waist','Waist','right'],[7,'legs','Legs','right'],
  [8,'feet','Feet','right'],[11,'finger1','Ring 1','right'],[12,'finger2','Ring 2','right'],
  [13,'trinket1','Trinket 1','right'],[14,'trinket2','Trinket 2','right'],
  [16,'mainHand','Main hand','weapon'],[17,'offHand','Off hand','weapon'],[18,'ranged','Ranged','weapon']
];
const QUALITY_NAMES = ['Poor','Common','Uncommon','Rare','Epic','Legendary','Artifact','Heirloom'];
let armoryData = {characters:{},icons:{}};
function trustedImage(value){
  if(typeof value!=='string')return '';
  try{const url=new URL(value);return url.protocol==='https:'&&['render.worldofwarcraft.com','wow.zamimg.com'].includes(url.hostname)&&!url.username&&!url.password&&!url.port?url.href:'';}catch{return '';}
}
function slotGlyph(slot){
  const paths={
    head:'M8 21v-8a8 8 0 0 1 16 0v8l-5 4v-8h-6v8z M8 13h16',
    neck:'M7 7c0 15 18 15 18 0 M16 20l4 4-4 5-4-5z',
    shoulder:'M4 20l3-9 7-3 2 7 2-7 7 3 3 9-8 3-4-5-4 5z',
    back:'M11 5h10l5 22-10-3-10 3z M11 5l5 6 5-6',
    chest:'M11 5l5 3 5-3 7 8-5 4v10H9V17l-5-4z',
    shirt:'M11 5l5 3 5-3 7 8-5 4v10H9V17l-5-4z',
    tabard:'M10 5h12v22l-6-4-6 4z M10 11h12',
    wrist:'M8 6l12-2 5 22-12 2z M10 13l12-2 M12 21l12-2',
    hands:'M9 26l-4-9 3-2 3 3V7h3v8V4h3v11V6h3v10l3-5 3 2-4 13z',
    waist:'M4 12h24v10H4z M13 10h6v14h-6z',
    legs:'M8 5h16l2 23h-8l-2-13-2 13H6z M8 10h16',
    feet:'M10 4h12l-2 15 7 4v5H6v-7l4-4z M9 11h12',
    finger1:'M10 10l6-6 6 6-6 6z M10 13a9 9 0 1 0 12 0',
    finger2:'M10 10l6-6 6 6-6 6z M10 13a9 9 0 1 0 12 0',
    trinket1:'M16 3l4 8 9 5-9 5-4 8-4-8-9-5 9-5z',
    trinket2:'M16 3l4 8 9 5-9 5-4 8-4-8-9-5 9-5z',
    mainHand:'M8 24L25 4l3-1-1 4-17 19 M5 19l9 8 M4 28l4-4',
    offHand:'M5 7l11-4 11 4v9c0 7-11 13-11 13S5 23 5 16z M16 6v19',
    ranged:'M6 28L23 8 M20 4l5 1 3 5-5-1z M10 3v4 M5 10h4'
  };
  return `<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${paths[slot]||paths.trinket1}"/></svg>`;
}
function equippedItem(c,slot){return list(c.equipment).find(i=>num(i.slot)===slot[0]||i.slotName===slot[1]);}
function gearIcon(item,slot){
  const icon=trustedImage(armoryData.icons?.[String(item?.itemID)]?.url);
  return `<span class="gear-icon"><span class="slot-glyph">${slotGlyph(slot[1])}</span>${icon?`<img src="${e(icon)}" alt="" loading="lazy" data-gear-icon>`:''}</span>`;
}
function gearSlot(c,slot){
  const item=equippedItem(c,slot);
  if(!item)return `<div class="gear-slot empty-slot">${gearIcon(null,slot)}<span class="gear-copy"><span class="slot-label">${e(slot[2])}</span><span class="empty-slot-label">Empty slot</span></span></div>`;
  return `<button class="gear-slot rarity-${num(item.quality)}" data-equip-slot="${slot[0]}" aria-label="${e(slot[2]+': '+(item.name||'Item '+item.itemID)+'. View item details')}">${gearIcon(item,slot)}<span class="gear-copy"><span class="slot-label">${e(slot[2])}</span><span class="gear-name">${e(item.name||'Item '+item.itemID)}</span><span class="gear-level">${item.itemLevel!=null?'Item level '+e(item.itemLevel):'Item level not recorded'}</span></span><span class="gear-chevron" aria-hidden="true">↗</span></button>`;
}
function portraitHTML(c){
  const media=armoryData.characters?.[c.id]||{},render=trustedImage(media.render),background=trustedImage(media.background);
  const sameGear=list(media.renderEquipment).map(num).sort((a,b)=>a-b).join(',')===list(c.equipment).map(i=>num(i.itemID)).sort((a,b)=>a-b).join(',');
  return `<figure class="character-stage ${render?'has-render':''}">
    ${render&&background?`<img class="character-background" src="${e(background)}" alt="" aria-hidden="true">`:''}
    <div class="portrait-halo" aria-hidden="true"></div>
    <div class="portrait-visual"><div class="portrait-placeholder"><span class="portrait-monogram" aria-hidden="true">${e(c.character.name[0])}</span><strong>Awaiting a character image</strong><p>An automatic portrait could not be retrieved.<br>Your saved equipment is still shown.</p><span class="pill">${e(c.character.race)} ${e(c.character.class)}</span></div>
    ${render?`<img class="character-render" src="${e(render)}" alt="${e(c.character.name)} Sundercore wearing equipment from Blizzard’s character image" data-character-render>`:''}</div>
    <figcaption><span class="portrait-caption-title">${e(c.character.name)} <span>Sundercore</span></span><span>${e(c.character.race)} · ${e(c.character.class)} · Level ${e(c.character.level)}</span>${render?`<small>Blizzard image · ${e(date(media.renderUpdatedAt))}${media.status==='cached'?' · last available image':''}</small><small>${sameGear?'Equipped item IDs match your snapshot.':'Appearance may differ from your saved gear.'}</small>`:`<small>Image availability is checked with each site update.</small>`}</figcaption>
  </figure>`;
}
function equipment(c){
  const gear=list(c.equipment),goals=orderedGoals(c).filter(g=>g.category==='Gear'),theme=c.character.classToken==='DRUID'?'druid':'warlock';
  const groups=group=>ARMORY_SLOTS.filter(s=>s[3]===group).map(s=>gearSlot(c,s)).join('');
  const primary=list(c.professions).filter(p=>p.isPrimary);
  return `<div class="view-header armory-heading"><div><div class="eyebrow">THE ARMORY</div><h2>Equipped for the journey.</h2><p>Select an item to inspect its saved details.</p></div><button class="button secondary" data-share-armory>Copy character link ↗</button></div>
  <section class="armory-shell ${theme}" aria-label="${e(c.character.name)} equipped gear">
    <div class="armory-strip"><span><strong>${gear.length}</strong> / 19 slots equipped</span><span><span class="tiny-dot"></span> FROM YOUR ADDON SNAPSHOT</span></div>
    <div class="armory-grid"><div class="gear-column gear-left">${groups('left')}</div>${portraitHTML(c)}<div class="gear-column gear-right">${groups('right')}</div><div class="weapon-slots">${groups('weapon')}</div></div>
    <div class="armory-footer"><span>${e(c.character.faction||'Azeroth')} <span class="separator">·</span> ${e(c.character.zone||'Location not recorded')}</span><span>${e(c.bags?.free??'—')} bag slots free</span></div>
  </section>
  <div class="armory-under"><section class="panel armory-professions"><div class="panel-header"><h2>Trades of the journey</h2><a href="#professions/${e(c.id)}" class="small-link">All professions ↗</a></div><div class="profession-strip">${primary.length?primary.map(p=>`<div><strong>${e(p.name)}</strong><span>${fmt(p.skill)} <small>/ ${fmt(p.maxSkill)}</small></span>${meter(p.skill,p.maxSkill)}</div>`).join(''):'<p class="muted">No primary professions recorded yet.</p>'}</div></section><aside class="armory-note"><span class="eyebrow">KEEP YOUR ARMORY CURRENT</span><p>Click <strong>Update SunderCore</strong> in the compact HUD. Your saved gear appears here after the watcher publishes it.</p><small>Character images update on Blizzard’s schedule and can lag behind your gear.</small></aside></div>
  ${c.gearPlan?`<section class="panel section-gap"><div class="panel-header"><div><h2>Your next gear upgrades</h2><p>Compare current equipment with sourced targets.</p></div><a class="button secondary" href="#upgrades/${e(c.id)}">Open upgrade planner ↗</a></div></section>`:goals.length?`<section class="panel section-gap"><div class="panel-header"><h2>Upgrades to work toward</h2></div>${goalsHTML(goals,20)}</section>`:''}
  <p class="source-note">Equipped items come from Character Ledger. Character artwork is provided by Blizzard; item icons by Blizzard and Wowhead. Gear goals are curated suggestions, not simulated upgrade rankings.</p>`;
}
function equipmentDetails(c,slotId){
  const slot=ARMORY_SLOTS.find(s=>s[0]===num(slotId)),item=slot&&equippedItem(c,slot);
  if(!item)return '';
  const quality=QUALITY_NAMES[num(item.quality)]||'Unknown quality';
  return `<div class="item-detail rarity-${num(item.quality)}"><div class="item-detail-heading">${gearIcon(item,slot)}<div><div class="eyebrow">${e(slot[2])} · ${e(quality)}</div><h2 class="gear-name">${e(item.name||'Item '+item.itemID)}</h2></div></div><dl class="item-facts"><div><dt>Item level</dt><dd>${e(item.itemLevel??'Not recorded')}</dd></div><div><dt>Required level</dt><dd>${item.requiredLevel===0?'No level requirement':e(item.requiredLevel??'Not recorded')}</dd></div><div><dt>Item ID</dt><dd>${e(item.itemID)}</dd></div><div><dt>Captured</dt><dd>${e(date(c.exportedAt))}</dd></div></dl><p>Detailed stat bonuses and enchants are not included in this snapshot. Open the item reference to explore its base attributes.</p><a class="button secondary" href="https://www.wowhead.com/forever/item=${num(item.itemID)}" target="_blank" rel="noopener noreferrer">View item reference ↗</a></div>`;
}
async function loadArmory(){
  try{const response=await fetch('data/armory.json?refresh='+Date.now(),{cache:'no-cache'});if(!response.ok)return;const data=await response.json();if(data.schemaVersion!==1||!data.characters||!data.icons)return;const changed=JSON.stringify(armoryData)!==JSON.stringify(data);armoryData=data;if(changed&&current())render();}catch{/* Gear stays usable if optional artwork is unavailable. */}
}


function upgradeCard(c,r){
  const gain=Number.isFinite(r.gain)?`${r.gain>0?'+':''}${num(r.gain).toFixed(1)}`:'—';
  return `<article class="panel upgrade-card ${r.recommended?'upgrade-focus':''}"><div class="panel-header"><div><span class="eyebrow">${e(r.slotName)}${r.recommended?' · TODAY’S GEAR GOAL':r.group?' · GROUP CONTENT':''}</span><h3>${e(r.name)}</h3><span class="pill">${e(r.status)}</span></div><div class="upgrade-gain"><strong>${e(gain)}</strong><small>estimated stat points</small></div></div><div class="panel-content"><div class="upgrade-replace"><small>CURRENT EQUIPMENT</small><strong>${e(r.current)}</strong></div><p class="upgrade-source">⌖ ${e(r.source)}</p><p class="upgrade-action">${e(r.action)}</p>${r.waypoint?`<p class="source-note">Source coordinates: ${(num(r.waypoint.x)*100).toFixed(1)}, ${(num(r.waypoint.y)*100).toFixed(1)} · in-game map ${fmt(r.waypoint.map)}</p>`:''}<details><summary>Stat comparison & materials</summary>${list(r.statChanges).length?`<div class="table-wrap"><table class="upgrade-stats"><thead><tr><th>Stat</th><th>Current</th><th>Target</th><th>Change</th></tr></thead><tbody>${list(r.statChanges).map(v=>`<tr><td>${e(v.stat)}</td><td>${fmt(v.before)}</td><td>${fmt(v.after)}</td><td class="${v.delta>0?'stat-positive':'stat-negative'}">${v.delta>0?'+':''}${fmt(v.delta)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">A reliable stat comparison is not available for this item yet.</p>'}${list(r.materials).length?`<h4>Materials per craft</h4><ul>${list(r.materials).map(m=>`<li>${fmt(m.count)} ${e(m.name)}</li>`).join('')}</ul><p>Queue this upgrade in game to reserve ingredients and add material farms to your projects.</p>`:''}<p class="source-note">Level required: ${r.requiredLevel==null?'not recorded':fmt(r.requiredLevel)}. Review the complete tooltip for procs, set bonuses, enchantments and special effects.</p></details><a class="small-link" href="https://www.wowhead.com/forever/item=${num(r.itemID)}" target="_blank" rel="noopener noreferrer">Item reference ↗</a></div></article>`;
}
function upgrades(c){
  const p=c.gearPlan;if(!p)return `<div class="view-header"><div><h2>A clearer path to better gear.</h2><p>Your equipped items, compared with practical next upgrades.</p></div></div><section class="panel">${empty('Save a fresh gear plan','Use Update SunderCore on this character with Character Ledger 1.5 or newer. Gear comparisons will appear after the watcher syncs.','◇')}</section>`;
  const all=list(p.upgrades).filter(r=>!r.ignored),ready=all.filter(r=>r.eligible),soon=all.filter(r=>!r.eligible&&!r.later&&Number.isFinite(r.gain)),later=all.filter(r=>r.later||!Number.isFinite(r.gain));
  return `<div class="view-header"><div><span class="eyebrow">EQUIPPED → NEXT UPGRADE</span><h2>Make the next drop count.</h2><p>${e(p.profile)} · ${e(p.profileOrigin||'Selected profile')} · solo farming and crafting first</p></div><a class="button secondary" href="#equipment/${e(c.id)}">View armory ↗</a></div><p class="source-note">Merchant’s Favor: ${p.merchantFavor?.quantity==null?'not recorded':fmt(p.merchantFavor.quantity)}. Recipe unlock prices appear after a vendor price has been recorded in game.</p><div class="upgrade-summary"><div><strong>${ready.length}</strong><span>Practical next steps</span></div><div><strong>${soon.length}</strong><span>Group / source review</span></div><div><strong>${fmt(p.pending)}</strong><span>Awaiting item data</span></div></div><div class="notice">${e(p.model)} One actionable gear goal can join Today; dungeon upgrades stay in Soon. Change the profile, track or skip a target, and queue crafts in <strong>/chargear</strong>.</div><section class="section-gap"><div class="panel-header"><div><h2>Worth working toward now</h2><p>Owned upgrades, learned crafts and sourced solo opportunities.</p></div></div>${ready.length?`<div class="grid-two upgrade-grid">${ready.map(r=>upgradeCard(c,r)).join('')}</div>`:`<div class="panel">${empty('No verified immediate upgrade','Review the alternatives below, scan your learned recipes in game, or wait for pending item data.','◇')}</div>`}</section>${soon.length?`<details class="completed-projects"><summary>Soon · groups & source checks · ${soon.length} targets</summary><div class="panel-header"><div><h2>Soon · groups & source checks</h2><p>These need a group, prerequisite checks, or a more reliable source.</p></div></div><div class="grid-two upgrade-grid">${soon.map(r=>upgradeCard(c,r)).join('')}</div></details>`:''}${later.length?`<details class="completed-projects"><summary>Later & pending · ${later.length} targets</summary><div class="grid-two upgrade-grid">${later.map(r=>upgradeCard(c,r)).join('')}</div></details>`:''}<p class="source-note">${e(p.source)}. ${e(p.coverage)} Snapshot ${e(date(c.exportedAt))}. The website displays your saved plan; it does not change in-game goals.</p>`;
}

function activity(c){const sessions=[...list(c.sessions)];if(c.activeSession)sessions.unshift(c.activeSession);sessions.sort((a,b)=>num(b.started)-num(a.started));const unsupported=c.coverage?.sessions==='Not exported by this addon version';return `<div class="view-header"><div><h2>The story of each outing.</h2><p>Recorded session time includes travel and downtime, excluding explicit pauses.</p></div></div>${sessions.length?`<div class="stack">${sessions.map(s=>{const seconds=sessionSeconds(s,c.exportedAt),hasReceived=s.receivedLoot!==null&&typeof s.receivedLoot==='object'&&!Array.isArray(s.receivedLoot),received=hasReceived?Object.values(s.receivedLoot).reduce((a,v)=>a+num(v),0):null,knownXP=Number.isFinite(s.xp);return `<section class="panel"><div class="panel-header"><div><h2>${e(s.label||s.zone||'Recorded outing')}</h2><p>${s.started?e(date(num(s.started)*1000)):'Start not recorded'}</p></div><span class="pill">${s.ended?'FINISHED':s.pausedAt?'PAUSED AT SNAPSHOT':'SAVED IN PROGRESS'}</span></div><div class="session-grid"><div><small>Session time</small><strong>${seconds===null?'—':`${Math.floor(seconds/60)}m ${Math.floor(seconds%60)}s`}</strong></div><div><small>Kills recorded</small><strong>${Number.isFinite(s.kills)?fmt(s.kills):'—'}</strong></div><div><small>Total XP gained</small><strong>${knownXP?fmt(s.xp):'—'}</strong></div><div><small>XP per session hour</small><strong>${seconds>0&&knownXP?fmt(Math.round(s.xp*3600/seconds)):'—'}</strong></div><div><small>Items received</small><strong>${received===null?'—':fmt(received)}</strong></div></div></section>`;}).join('')}</div>`:`<section class="panel">${empty(unsupported?'Outings were not exported':'The first outing starts in game.',unsupported?'This snapshot predates outing summaries. Save and sync with Character Ledger 1.3 or newer to include them.':'Start an outing in Character Ledger’s planner, grind a camp, and end the outing. Save and sync to see your recorded kills, XP, and received loot here.','↗')}</section>`}<div class="notice">Total XP includes quest rewards and rested XP. Travel and idle time affect session rates, so they do not establish the fastest camp. Observed loot windows and received items are different measurements. Missing collection data is shown as —; a measured zero stays 0. Unfinished outings stay frozen at the character’s snapshot time.</div>`;}
function sessionSeconds(s,capturedAt){if(Number.isFinite(s.seconds))return Math.max(0,s.seconds);const elapsed=Number.isFinite(s.elapsed)?s.elapsed:0;if(s.pausedAt)return Number.isFinite(s.elapsed)?Math.max(0,s.elapsed):null;const start=s.segmentAt??s.started,end=Number.isFinite(s.ended)?s.ended:Date.parse(capturedAt)/1000;if(!Number.isFinite(start)||!Number.isFinite(end))return null;return Math.max(0,elapsed+Math.max(0,end-start));}
function sourceHTML(c){const src=c?.fieldPlan?.dataSource;return `<div class="source-note">${src?`<p>Loot reference: <a href="https://everloot.app/" target="_blank" rel="noopener noreferrer">${e(src.provider||'Everloot')}</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · Source captured ${e(date(src.capturedAt))}.</p><p>${e(src.status||'Community observations; coverage varies by creature and source type.')}</p>`:'<p>This older snapshot predates the Forever reference pack. Save a new snapshot with Character Ledger 1.3+ to include its source information.</p>'}<p>Suggestions are generated by the in-game addon. The website displays the saved plan.</p></div>`;}
let dailyBucket='today';
const DAILY_BUCKETS={today:'Today',soon:'Soon',someday:'Someday',reviewed:'Dismissed in game',snoozed:'Set aside in game'};
const FOCUS_LABELS={grind:'Grind mobs',balanced:'Balanced',crafting:'Crafting',gold:'Make gold'};
function dailyFor(c){
  if([1,2,3].includes(c.dailyPlan?.version))return c.dailyPlan;
  const tasks=orderedGoals(c).map(g=>({...g,kind:g.category,open:'Progression'}));
  const ready=tasks.filter(g=>g.status==='Ready to turn in'||g.id==='bags:room'||g.id==='training:now');
  const chosen=new Set(ready.slice(0,3).map(g=>g.id));
  return {legacy:true,mode:'balanced',day:null,today:ready.slice(0,3),soon:tasks.filter(g=>g.category!=='Gear'&&!chosen.has(g.id)),someday:tasks.filter(g=>g.category==='Gear'),reviewed:[],snoozed:[],projects:[]};
}
function allDailyTasks(c){
  const p=dailyFor(c),seen=new Set();
  return Object.keys(DAILY_BUCKETS).flatMap(k=>list(p[k])).filter(t=>{if(!t.id||seen.has(t.id))return false;seen.add(t.id);return true;});
}
function dailyCheckKey(c,p){return `daily-checks:${c.id}:${p.day||c.exportedAt}`;}
function routeLink(view,c){return `#${view}/${encodeURIComponent(c.id)}`;}
function primaryProfessions(c){return list(c.professions).filter(p=>p.isPrimary);}
function taskLink(t,c){
  const view={Gear:'upgrades',Projects:'projects',Checklist:'field',Camps:'field',Outing:'field',Professions:'professions',Gold:'gold',Progression:'overview'}[t.open];
  return view?routeLink(view,c):null;
}
function taskAction(t){return t.kind==='Sell'?'Review sale':t.kind==='Disenchant'?'Review spare':t.kind==='Farm'?'View farm steps':t.open==='Gear'?'Compare upgrade':t.open==='Projects'?'View materials':'View next step';}
function taskCard(c,p,t,index,featured=false){
  const checked=list(savedGet(dailyCheckKey(c,p),[])).includes(t.id);
  return `<article class="daily-task journal-task ${featured?'featured-task':''} ${checked?'locally-checked':''}">
    <div class="daily-task-kicker">${featured?'NEXT UP':`NEXT ${index+1}`} <span aria-hidden="true">/</span> ${e(t.profession||t.kind||'Saved task')}${t.pinned?' <span class="pill gold">TRACKED IN GAME</span>':''}</div>
    <h3>${e(t.title||'Review saved task')}</h3>
    <div class="daily-task-meta"><span class="pill ${t.done?'green':''}">${e(t.done?'Materials ready':t.status||'Suggested')}</span>${t.need!=null?`<span>${fmt(t.have)} / ${fmt(t.need)} ${t.open==='Projects'?'crafts completed':'allocated'}</span>`:''}<span class="review-indicator" ${checked?'':'hidden'}>Reviewed on this device</span></div>
    ${featured?`<p class="task-summary">${e(t.nextAction||t.why||t.action?.split('\n')[0]||'Review the saved requirements before starting.')}</p>`:''}
    <div class="task-actions"><button class="button ${featured?'':'secondary'}" data-task-details="${e(t.id)}">${taskAction(t)} <span aria-hidden="true">↗</span></button>
    <details class="task-more"><summary aria-label="More options for ${e(t.title)}">More</summary><div class="task-more-options"><button class="text-button" data-task-details="${e(t.id)}">Why & details</button><label><input type="checkbox" data-daily-check="${e(t.id)}" ${checked?'checked':''}> Reviewed on this device</label><small>This does not complete the task in game.</small>${taskLink(t,c)?`<a class="small-link" href="${taskLink(t,c)}">Open related tool ↗</a>`:''}</div></details></div>
  </article>`;
}
function dailyTasksHTML(c,p){
  const tasks=list(p[dailyBucket]);
  return tasks.length?`<div class="daily-tasks">${tasks.map((t,i)=>taskCard(c,p,t,i)).join('')}</div>`:empty('Nothing here right now.','Choose another group or set a new goal in game.');
}
function trackedObjective(c){
  const p=dailyFor(c),pinned=allDailyTasks(c).find(t=>t.pinned);
  if(pinned)return `<div class="tracked-content"><span class="eyebrow">TRACKED IN YOUR ADDON</span><h3>${e(pinned.title)}</h3><p>${e(pinned.status||'Review saved goal')}</p>${pinned.need!=null?`${meter(pinned.have,pinned.need)}<p class="panel-caption">${fmt(pinned.have)} / ${fmt(pinned.need)} ${pinned.open==='Projects'?'crafts completed':'allocated'}</p>`:''}<button class="button secondary wide" data-task-details="${e(pinned.id)}">${taskAction(pinned)} ↗</button></div>`;
  if(p.camp?.chosen){
    const match=list(c.fieldPlan?.spots).find(r=>r.spot?.id===p.camp.id);
    return `<div class="tracked-content"><span class="eyebrow">TRACKED IN YOUR ADDON</span><h3>${e(p.camp.name)}</h3><p>⌖ ${e(p.camp.zone||'Location not recorded')}</p><span class="pill gold">Chosen outing</span>${!match?'<p class="panel-caption">This camp is outside the current recommendation list. Review its level suitability in game.</p>':''}<a class="button secondary wide section-gap" href="${routeLink('field',c)}">Review farming locations ↗</a></div>`;
  }
  return `<div class="tracked-content"><span class="eyebrow">YOUR TRACKED OBJECTIVE</span><h3>Choose one thing to follow.</h3><p>In Character Ledger, choose <strong>More → Track this</strong>, then Update SunderCore. Your saved choice appears here.</p><a class="small-link" href="${routeLink('goals',c)}">Explore your goals ↗</a></div>`;
}
function professionMini(c){
  const profs=primaryProfessions(c);
  return `<section class="panel"><div class="panel-header"><h2>Both professions</h2><a class="small-link" href="${routeLink('goals',c)}">My Goals ↗</a></div><div class="panel-content">${profs.length?profs.map(p=>`<div class="profession-mini"><span>${e(p.name)}</span><strong>${fmt(p.skill)} <small>/ ${fmt(p.maxSkill)}</small></strong></div>`).join(''):'<p class="panel-caption">No primary professions recorded. Learn a trade in game, then save a snapshot.</p>'}</div></section>`;
}
function today(c){
  const p=dailyFor(c),tasks=list(p.today),visible=tasks.slice(0,3);
  return `<div class="view-header journal-heading"><div><div class="eyebrow">TODAY</div><h2>Your next step, made simple.</h2><p>${p.legacy?'Basic plan from an older snapshot. Update Character Ledger and save to share your chosen daily plan.':`${e(FOCUS_LABELS[p.mode]||'Saved focus')} · Saved plan for ${e(p.day||'this snapshot')}`}</p></div><a class="small-link" href="${routeLink('ideas',c)}">More ideas ↗</a></div>
  <div class="journal-layout"><div class="stack"><section class="panel today-board" aria-label="Daily checklist">${visible.length?visible.map((t,i)=>taskCard(c,p,t,i,i===0)).join(''):empty('Your checklist is clear.','Browse more ideas or choose a project in My Goals.')}${tasks.length>3?`<details class="extra-tasks"><summary>${tasks.length-3} more tasks in your saved checklist</summary>${tasks.slice(3).map((t,i)=>taskCard(c,p,t,i+3)).join('')}</details>`:''}<div class="daily-local-note">Website reviews stay on this device. Change your plan in game.</div></section><div class="journal-help"><span>Focus and checklist size are set in <strong>/chartoday</strong>.</span><button class="text-button" data-manage>How to update ↗</button></div></div><aside class="stack" aria-label="Tracked goal and professions"><section class="panel tracked-panel">${trackedObjective(c)}</section>${professionMini(c)}</aside></div>`;
}
function professionGoal(c,prof){
  return allDailyTasks(c).find(t=>(prof.skillLineID!=null&&t.skillLineID===prof.skillLineID)||(prof.name&&(t.profession===prof.name||t.title?.startsWith(prof.name+':'))));
}
function myGoals(c){
  const p=dailyFor(c),profs=primaryProfessions(c),active=list(p.projects).filter(q=>q.remaining>0&&!q.cancelled),tracked=list(c.gearPlan?.upgrades).filter(r=>r.tracked&&!r.ignored);
  return `<div class="view-header journal-heading"><div><span class="eyebrow">MY GOALS</span><h2>Keep sight of what you’re building.</h2><p>Your professions, saved projects and the materials they need.</p></div><a class="small-link" href="${routeLink('projects',c)}">Project details ↗</a></div>
  ${profs.length?`<div class="grid-two profession-goals">${profs.map(prof=>{const goal=professionGoal(c,prof);return `<section class="panel profession-goal"><div class="panel-header"><div><span class="eyebrow">PRIMARY PROFESSION</span><h2>${e(prof.name)}</h2></div><span class="profession-rank">${fmt(prof.skill)} <small>/ ${fmt(prof.maxSkill)}</small></span></div><div class="panel-content">${meter(prof.skill,prof.maxSkill)}<p>${e(goal?.title||'Review your next training and recipe milestones.')}</p>${goal?`<span class="pill">${e(goal.status||'Saved suggestion')}</span>`:''}<a class="small-link" href="${routeLink('professions',c)}">View profession progress ↗</a></div></section>`;}).join('')}</div>`:`<section class="panel">${empty('Your first trade starts in game.','No primary professions were captured for this character. Learn a profession and open it before saving.','⚒')}</section>`}
  <div class="journal-layout section-gap"><div class="stack"><section class="panel"><div class="panel-header"><div><h2>Crafting projects</h2><p>${active.length} active or paused</p></div><a class="small-link" href="${routeLink('projects',c)}">View all ↗</a></div>${active.length?`<div class="panel-content">${active.map(q=>`<a class="goal-row" href="${routeLink('projects',c)}"><span><strong>${e(q.name)}</strong><small>${e(q.status)} · ${fmt(q.completed)} / ${fmt(q.total)} crafts completed</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div>`:empty('Choose something to make.','Queue a learned recipe in Character Ledger. Your project carries forward until you finish it.','⚒')}</section>${tracked.length?`<section class="panel"><div class="panel-header"><h2>Tracked upgrades</h2></div><div class="panel-content">${tracked.map(r=>`<a class="goal-row" href="${routeLink('upgrades',c)}"><span><strong>${e(r.name)}</strong><small>${e(r.status)}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`:''}</div><section class="panel"><div class="panel-header"><div><h2>Materials for your goals</h2><p>Shared across projects and stock targets</p></div><a class="small-link" href="${routeLink('field',c)}">Find farms ↗</a></div>${materialsHTML(c)}</section></div><p class="source-note">Materials ready means you can review the next craft. Projects only complete after successful crafting casts recorded in game.</p>`;
}
const BROWSE_GROUPS=[
  {title:'Adventure',items:[['field','Grind camps','Compare locations and material needs.','⌖'],['upgrades','Gear upgrades','Compare your gear and where to find upgrades.','↟'],['equipment','Character armory','See equipped items and your character portrait.','◇'],['ideas','More ideas','Soon, Someday and tasks set aside.','☷']]},
  {title:'Professions & gold',items:[['gold','Gold routine','Saved farming, crafting and selling opportunities.','◉'],['professions','Profession progress','Ranks, recipe scans and training milestones.','⚒'],['projects','Crafting projects','Materials, progress and paused projects.','▧'],['inventory','Inventory','Search everything in your saved bags.','▦']]},
  {title:'Journal & reference',items:[['activity','Recorded outings','Your recorded time, XP and loot totals.','↗'],['overview','Progression overview','The complete saved progression plan.','◈'],['sources','About the data','Snapshot freshness, sources and coverage.','ⓘ']]}
];
function browse(c){return `<div class="view-header journal-heading"><div><span class="eyebrow">BROWSE</span><h2>Everything you need, when you need it.</h2><p>Open a tool to explore. Your next step stays on Today.</p></div></div><div class="browse-groups">${BROWSE_GROUPS.map(group=>`<section class="browse-group"><h3>${e(group.title)}</h3>${group.items.map(([view,title,description,icon])=>`<a class="browse-card" href="${routeLink(view,c)}"><span class="browse-icon" aria-hidden="true">${icon}</span><span><strong>${title}</strong><small>${description}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</section>`).join('')}</div>`;}
function moreIdeas(c){
  const p=dailyFor(c),bucket=dailyBucket==='today'?'soon':dailyBucket,tasks=list(p[bucket]);
  const options=Object.entries(DAILY_BUCKETS).filter(([key])=>key!=='today');
  return `<div class="view-header journal-heading"><div><span class="eyebrow">MORE IDEAS</span><h2>Keep the possibilities. Pick one later.</h2><p>Saved prerequisites, longer goals and reminders from your addon.</p></div><label class="idea-filter">Show <select data-idea-filter>${options.map(([key,title])=>`<option value="${key}" ${key===bucket?'selected':''}>${title} (${list(p[key]).length})</option>`).join('')}</select></label></div><p class="source-note">Dismissed and set-aside states belong to the saved plan day, ${e(p.day||date(c.exportedAt))}. Browser reviews are separate.</p><section class="panel idea-list">${tasks.length?tasks.map((t,i)=>taskCard(c,p,t,i)).join(''):empty('Nothing here right now.','Choose a different group to explore.')}</section>`;
}
function gold(c){
  const p=dailyFor(c),tasks=allDailyTasks(c).filter(t=>t.id.startsWith('gold:'));
  return `<div class="view-header journal-heading"><div><span class="eyebrow">GOLD ROUTINE</span><h2>Make use of what you have.</h2><p>Opportunities from your saved character and auction observations.</p></div></div><div class="notice">These are saved estimates, not live auction prices or guaranteed sales. Check prices, materials and deposits in game before acting.</div>${tasks.length?['Sell','Farm','Craft','Disenchant','Review'].map(kind=>{const rows=tasks.filter(t=>(['Sell','Farm','Craft','Disenchant'].includes(t.kind)?t.kind:'Review')===kind);return rows.length?`<section class="panel section-gap"><div class="panel-header"><h2>${{Sell:'Sell surplus',Farm:'Farming opportunities',Craft:'Crafting experiments',Disenchant:'Disenchant review',Review:'Before you begin'}[kind]}</h2><span class="pill">${rows.length}</span></div>${rows.map((t,i)=>taskCard(c,p,t,i)).join('')}</section>`:'';}).join(''):`<section class="panel section-gap">${empty('No gold routine in this snapshot.','Choose Make gold in Character Ledger, scan the auction house and use Update SunderCore.','◉')}</section>`}`;
}
function sources(c){return `<div class="view-header"><div><h2>Your character, as last saved.</h2><p>Captured ${e(date(c.exportedAt))}. This website does not show live game state.</p></div></div><section class="panel"><div class="panel-content sources-content"><p>Character Ledger supplies the saved plan, gear, profession ranks and inventory. Sources and requirements remain attached to each task.</p><p>Reviewed on this device is a personal browser note. It does not complete quests, craft items or change your addon’s plan.</p>${sourceHTML(c)}</div></section>`;}
function taskDetails(c,id){
  const t=allDailyTasks(c).find(row=>row.id===id);if(!t)return null;
  const href=taskLink(t,c);
  return `<span class="eyebrow">${e(t.kind||'SAVED TASK')}</span><h2>${e(t.title)}</h2><span class="pill">${e(t.status||'Suggested')}</span><h3>Next action</h3><p class="preserve-lines">${e(t.action||t.nextAction||'Review this task in Character Ledger.')}</p>${t.why?`<h3>Why this task?</h3><p>${e(t.why)}</p>`:''}${t.source?`<details class="task-evidence"><summary>Source & confidence</summary><p class="preserve-lines">${e(t.source)}</p></details>`:''}<p class="source-note">Saved ${e(date(c.exportedAt))}. Check current requirements in game.</p>${href?`<a class="button" data-close-dialog href="${href}">Open ${e(VIEWS[href.slice(1).split('/')[0]])} ↗</a>`:''}`;
}

function projectMaterialSteps(m){const steps=[];if(num(m.missing)>0)steps.push(`${m.vendor?'Buy':'Acquire'} ${fmt(m.missing)}`);if(num(m.bank)>0)steps.push(`${steps.length?'withdraw':'Withdraw'} ${fmt(m.bank)}`);if(num(m.make)>0)steps.push(`Craft ${fmt(m.make)}`);return steps.join(' + ')||'Ready';}
function projects(c){
  const p=dailyFor(c),all=list(p.projects).filter(q=>!q.cancelled),active=all.filter(q=>q.remaining>0),complete=all.filter(q=>q.remaining===0);
  const card=q=>`<section class="panel project-card"><div class="panel-header"><div><span class="eyebrow">${q.paused?'ON HOLD':q.remaining===0?'COMPLETED PROJECT':'CRAFTING PROJECT'}</span><h2>${e(q.name)}</h2></div><span class="pill ${q.status==='Ready to craft'?'green':''}">${e(q.status)}</span></div><div class="panel-content"><div class="project-progress"><strong>${fmt(q.completed)} / ${fmt(q.total)}</strong><span>crafting casts completed · ${fmt(q.remaining)} left</span></div>${meter(q.completed,q.total)}${q.paused?'<p class="panel-caption">Paused projects release their material reservations. Resume in game to recalculate.</p>':''}${q.status==='Needs recipe scan'?'<p class="notice">Open this profession in game to refresh the learned recipe and its materials.</p>':''}${list(q.materials).length?`<div class="project-materials">${list(q.materials).map(m=>`<div><span><strong>${e(m.name||'Item '+m.id)}</strong><small>${fmt(m.bag)} / ${fmt(m.need)} reserved in bags</small></span><span>${e(projectMaterialSteps(m))}</span></div>`).join('')}</div>`:''}<p class="panel-caption">${q.remaining?'Materials are allocated in project order. Check tools, cooldowns, and location in your profession window.':'Completion records successful crafting casts; it does not guarantee skill points or a particular output quantity.'}</p></div></section>`;
  return `<div class="view-header"><div><div class="eyebrow">MAKE SOMETHING WORTH KEEPING</div><h2>From a recipe to a finished project.</h2><p>Shared materials, intermediate crafts, and remaining work from your saved plan.</p></div><span class="pill">${active.length} active · ${complete.length} complete</span></div>${all.length?`<div class="grid-two">${active.map(card).join('')}</div>${complete.length?`<details class="completed-projects"><summary>Completed projects (${complete.length})</summary><div class="grid-two">${complete.map(card).join('')}</div></details>`:''}`:`<section class="panel">${empty('Your first project starts in game',p.legacy?'This snapshot predates project tracking. Update Character Ledger, open your profession, then save and sync.':'Open /chartoday, choose Browse → Known recipes, select a learned recipe, and queue the number of crafting casts.','⚒')}</section>`}<div class="notice">Manage priorities, pauses, and cancellations in the addon’s <strong>My Goals</strong> page. Bank materials are last-seen stock and must be withdrawn before crafting.</div>`;
}

function render(){
  const c=current();if(!c)return;state.selected=c.id;
  $('#roster-count').textContent=String(state.roster.length).padStart(2,'0');
  $('#roster').innerHTML=state.roster.map(r=>`<button class="character-button ${r.id===c.id?'active':''}" data-character="${e(r.id)}" aria-pressed="${r.id===c.id}"><span class="avatar ${r.character.classToken==='DRUID'?'druid':''}" aria-hidden="true">${e(r.character.name[0])}</span><span><span class="character-name">${e(r.character.name)}</span><small>${e(r.character.race)} ${e(r.character.class)}</small></span><span class="level">${e(r.character.level)}</span></button>`).join('');
  const mainPage=['today','goals','browse'].includes(state.view),parent=mainPage?state.view:'browse';
  $('#breadcrumb').textContent=mainPage?VIEWS[state.view]:`Browse / ${VIEWS[state.view]}`;
  document.querySelectorAll('[data-view]').forEach(el=>{
    const selected=el.dataset.view===parent;el.classList.toggle('active',selected);el.href=routeLink(el.dataset.view,c);
    if(selected)el.setAttribute('aria-current',mainPage?'page':'location');else el.removeAttribute('aria-current');
  });
  $('#addon-version').textContent=`v${c.addonVersion}`;document.title=`${c.character.name} Sundercore · ${VIEWS[state.view]}`;
  const renderer={today,goals:myGoals,browse,ideas:moreIdeas,gold,sources,projects,upgrades,overview,field,inventory,professions,equipment,activity}[state.view];
  $('#main').innerHTML=hero(c)+(!mainPage?`<a class="back-link" href="${routeLink('browse',c)}">← Browse all tools</a>`:'')+renderer(c);
}
function route(){if($('#info-dialog').open)$('#info-dialog').close();if(location.hash==='#main'){if(!$('#main').querySelector('.hero'))render();$('#main').focus();return;}const [view,id]=location.hash.slice(1).split('/');state.view=VIEWS[view]?view:'today';if(id&&state.roster.some(c=>c.id===id)){state.selected=id;savedSet('sundercore-character',id);}state.filter='';render();}
async function loadRoster(silent=false){try{const response=await fetch(`data/characters.json${silent?'?refresh='+Date.now():''}`,{cache:'no-cache'});if(!response.ok)throw Error(`Snapshot request failed (${response.status})`);const data=await response.json();if(data.schemaVersion!==1||!Array.isArray(data.characters)||!data.characters.length)throw Error('No compatible character snapshots are available.');const sorted=[...data.characters].sort((a,b)=>num(b.character?.level)-num(a.character?.level));const hadRoster=state.roster.length>0,changed=JSON.stringify(sorted)!==JSON.stringify(state.roster);state.roster=sorted;if(!state.selected)state.selected=savedGet('sundercore-character',null);if(changed){if(hadRoster)render();else route();}return true;}catch(error){if(!state.roster.length)$('#main').innerHTML=`<section class="panel error">${empty('The chronicle could not load',error.message)}<div class="panel-content"><button class="button" data-refresh>Try again</button></div></section>`;if(!silent)notify('Could not refresh snapshots. Please try again.');return false;}}
function dialog(content){$('#dialog-content').innerHTML=content;$('#info-dialog').showModal();}
function showManage(){dialog(`<div class="eyebrow">OWNER CONTROLS</div><h2>Keep the chronicle current.</h2><p>This is a public, read-only website. Publishing is controlled by the repository owner’s GitHub login.</p><ol><li>In game, click <strong>Update SunderCore</strong> at the bottom of the compact HUD. It saves your character and reloads the UI.</li><li>Keep <strong>SunderCore Watcher</strong> running in the Windows tray. It detects the save and publishes it automatically.</li><li>Allow the GitHub Pages deployment to finish, then refresh this page.</li></ol><p>The optional watcher can sync future saved snapshots while it runs. No GitHub password or token is entered into this website.</p><a class="button" href="${REPOSITORY}" target="_blank" rel="noopener noreferrer">Open repository & update guide ↗</a>`);}
$('#manage-button').addEventListener('click',showManage);
$('#about-button').addEventListener('click',()=>dialog(`<div class="eyebrow">FROM AZEROTH, WITH CONTEXT</div><h2>A snapshot, not a live feed.</h2><p>Each character keeps their own last exported snapshot. Play a character, save in Character Ledger, and sync to update their journal. Dates are shown in your browser’s local time.</p><p>Public data includes character progress, carried items, equipment, professions, goals, and outing summaries. The exporter removes account identifiers, local paths, and raw item strings.</p><p>Personal checklist ticks are stored only in this browser. Publishing access belongs to the GitHub repository owner.</p>${sourceHTML(current())}`));
$('.dialog-close').addEventListener('click',()=>$('#info-dialog').close());
$('#info-dialog').addEventListener('click',event=>{if(event.target===$('#info-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
document.addEventListener('click',async event=>{
  if(event.target.closest('[data-manage]')){showManage();return;}
  if(event.target.closest('[data-close-dialog]'))$('#info-dialog').close();
  const task=event.target.closest('[data-task-details]');
  if(task){const content=taskDetails(current(),task.dataset.taskDetails);if(content)dialog(content);return;}
const horizon=event.target.closest('[data-daily-bucket]');if(horizon&&DAILY_BUCKETS[horizon.dataset.dailyBucket]){dailyBucket=horizon.dataset.dailyBucket;render();return;}const char=event.target.closest('[data-character]');if(char){location.hash=`${state.view}/${char.dataset.character}`;return;}const gear=event.target.closest('[data-equip-slot]');if(gear){const content=equipmentDetails(current(),gear.dataset.equipSlot);if(content)dialog(content);return;}if(event.target.closest('[data-share-armory]')){const url=location.href.split('#')[0]+'#equipment/'+current().id;try{await navigator.clipboard.writeText(url);notify('Character armory link copied.');}catch{dialog('<h2>Character link</h2><p class=overflow-wrap>'+e(url)+'</p>');}return;}if(event.target.closest('[data-refresh]')){const ok=await loadRoster(true);await loadArmory();notify(ok?'Latest published snapshots loaded.':'Could not refresh. Your last loaded snapshot is still shown.');return;}const camp=event.target.closest('[data-copy-camp]');if(camp){const s=current().fieldPlan.spots[Number(camp.dataset.copyCamp)].spot;const text=`${s.name} — ${s.zone}, ${(s.x*100).toFixed(1)}, ${(s.y*100).toFixed(1)} (Source: ${s.evidence||s.source||'Classic-derived; verify in game'})`;try{await navigator.clipboard.writeText(text);notify('Camp location copied.');}catch{dialog(`<h2>Camp location</h2><p>${e(text)}</p>`);}}});
document.addEventListener('change',event=>{
  if(event.target.matches('[data-idea-filter]')){dailyBucket=event.target.value;render();$('[data-idea-filter]').focus();return;}
if(event.target.matches('[data-daily-check]')){const c=current(),p=dailyFor(c),key=dailyCheckKey(c,p),checked=new Set(savedGet(key,[]));if(event.target.checked)checked.add(event.target.dataset.dailyCheck);else checked.delete(event.target.dataset.dailyCheck);if(!savedSet(key,[...checked]))notify('Checkmark works for this visit, but browser storage is unavailable.');const row=event.target.closest('.daily-task');row.classList.toggle('locally-checked',event.target.checked);row.querySelector('.review-indicator').hidden=!event.target.checked;return;}if(event.target.matches('[data-task]')){const key=`checklist:${current().id}`,checked=new Set(savedGet(key,[]));if(event.target.checked)checked.add(event.target.dataset.task);else checked.delete(event.target.dataset.task);if(!savedSet(key,[...checked]))notify('Checkmark works for this visit, but browser storage is unavailable.');}});
document.addEventListener('input',event=>{if(event.target.id==='inventory-search'){state.filter=event.target.value;$('#inventory-rows').innerHTML=inventoryRows(current());}});
window.addEventListener('hashchange',route);
document.addEventListener('error',event=>{const img=event.target;if(img.matches?.('[data-character-render]')){const stage=img.closest('.character-stage');stage.classList.remove('has-render');img.hidden=true;const notes=stage.querySelectorAll('figcaption small');if(notes[0])notes[0].textContent='Character image is temporarily unavailable.';if(notes[1])notes[1].textContent='Equipment still reflects your saved snapshot.';}else if(img.matches?.('[data-gear-icon]'))img.hidden=true;},true);
loadRoster();
loadArmory();
setInterval(()=>{if(!document.hidden){loadRoster(true);loadArmory();}},120000);
